BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS ci_master_sku (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL, sku text NOT NULL, product_name text NOT NULL, uom text NOT NULL DEFAULT 'EA', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,sku), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS ci_location (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL, code text NOT NULL, location_type text NOT NULL CHECK(location_type IN ('warehouse','store','qcommerce_darkstore','marketplace_custody','in_transit')), external_id text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,code), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS ci_channel_account (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL, platform text NOT NULL, external_account_id text NOT NULL, encrypted_credentials bytea, credential_iv bytea, credential_tag bytea, scopes text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'inactive', rate_state jsonb NOT NULL DEFAULT '{}', settings jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,platform,external_account_id), UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS ci_channel_mapping (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL, account_id uuid NOT NULL, master_sku_id uuid NOT NULL, external_sku text NOT NULL, listing_id text, catalog_id text, external_location_id text NOT NULL DEFAULT '', internal_location_id uuid, pack_size integer NOT NULL DEFAULT 1 CHECK(pack_size>0), active boolean NOT NULL DEFAULT false, approved_at timestamptz, FOREIGN KEY(tenant_id,account_id) REFERENCES ci_channel_account(tenant_id,id), FOREIGN KEY(tenant_id,master_sku_id) REFERENCES ci_master_sku(tenant_id,id), FOREIGN KEY(tenant_id,internal_location_id) REFERENCES ci_location(tenant_id,id), UNIQUE(tenant_id,account_id,external_sku,external_location_id));
CREATE TABLE IF NOT EXISTS ci_inventory_balance (tenant_id text NOT NULL, master_sku_id uuid NOT NULL, location_id uuid NOT NULL, on_hand bigint NOT NULL DEFAULT 0 CHECK(on_hand>=0), reserved_order bigint NOT NULL DEFAULT 0 CHECK(reserved_order>=0), reserved_cart bigint NOT NULL DEFAULT 0 CHECK(reserved_cart>=0), damaged bigint NOT NULL DEFAULT 0 CHECK(damaged>=0), quarantined bigint NOT NULL DEFAULT 0 CHECK(quarantined>=0), safety_stock bigint NOT NULL DEFAULT 0 CHECK(safety_stock>=0), version bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,master_sku_id,location_id), FOREIGN KEY(tenant_id,master_sku_id) REFERENCES ci_master_sku(tenant_id,id), FOREIGN KEY(tenant_id,location_id) REFERENCES ci_location(tenant_id,id), CHECK(reserved_order+reserved_cart+damaged+quarantined<=on_hand));
CREATE TABLE IF NOT EXISTS ci_inventory_event (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL, master_sku_id uuid NOT NULL, location_id uuid NOT NULL, event_key text NOT NULL, event_type text NOT NULL, delta_on_hand bigint NOT NULL DEFAULT 0, delta_reserved_order bigint NOT NULL DEFAULT 0, delta_reserved_cart bigint NOT NULL DEFAULT 0, delta_damaged bigint NOT NULL DEFAULT 0, delta_quarantined bigint NOT NULL DEFAULT 0, delta_safety_stock bigint NOT NULL DEFAULT 0, source text NOT NULL, external_reference text, payload_hash text NOT NULL, occurred_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(tenant_id,master_sku_id) REFERENCES ci_master_sku(tenant_id,id), FOREIGN KEY(tenant_id,location_id) REFERENCES ci_location(tenant_id,id), UNIQUE(tenant_id,event_key));
CREATE TABLE IF NOT EXISTS ci_reservation (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id text NOT NULL, master_sku_id uuid NOT NULL, location_id uuid NOT NULL, source text NOT NULL, external_order_id text NOT NULL, external_line_id text NOT NULL, quantity bigint NOT NULL CHECK(quantity>0), status text NOT NULL CHECK(status IN ('active','released','consumed')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,source,external_order_id,external_line_id), FOREIGN KEY(tenant_id,master_sku_id,location_id) REFERENCES ci_inventory_balance(tenant_id,master_sku_id,location_id));
CREATE TABLE IF NOT EXISTS ci_channel_stock (tenant_id text NOT NULL, mapping_id uuid NOT NULL REFERENCES ci_channel_mapping(id), target_quantity bigint NOT NULL DEFAULT 0, observed_quantity bigint, observed_at timestamptz, publish_state text NOT NULL DEFAULT 'pending', updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,mapping_id));
CREATE TABLE IF NOT EXISTS ci_outbox (id bigserial PRIMARY KEY, tenant_id text NOT NULL, task_type text NOT NULL, account_id uuid, mapping_id uuid, payload jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(tenant_id,task_type,mapping_id,payload));
CREATE INDEX IF NOT EXISTS ci_outbox_ready ON ci_outbox(available_at,id) WHERE status IN ('pending','retry');
CREATE TABLE IF NOT EXISTS ci_ingress (tenant_id text NOT NULL, source text NOT NULL, message_id text NOT NULL, payload_hash text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(tenant_id,source,message_id));
CREATE TABLE IF NOT EXISTS ci_sync_cursor (tenant_id text NOT NULL, account_id uuid NOT NULL REFERENCES ci_channel_account(id), stream text NOT NULL, cursor_value text, last_success_at timestamptz, PRIMARY KEY(tenant_id,account_id,stream));
CREATE OR REPLACE FUNCTION ci_deny_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'inventory events are immutable'; END $$;
DROP TRIGGER IF EXISTS ci_inventory_event_immutable ON ci_inventory_event;
CREATE TRIGGER ci_inventory_event_immutable BEFORE UPDATE OR DELETE ON ci_inventory_event FOR EACH ROW EXECUTE FUNCTION ci_deny_event_mutation();
COMMIT;
